<?php
require_once __DIR__.'/../../includes/layout.php';require_role(['Super Admin']);check_csrf();$error='';
if($_SERVER['REQUEST_METHOD']==='POST')try{
 $id=(int)($_POST['id']??0);$name=trim((string)($_POST['name']??''));$kind=(string)($_POST['kind']??'');$location=trim((string)($_POST['location']??''));$capacity=filter_var($_POST['capacity']??'',FILTER_VALIDATE_INT);$office=(int)($_POST['office_id']??0);
 if(strlen($name)<3||strlen($name)>120||strlen($location)<2||strlen($location)>160||!in_array($kind,['Room','Laboratory','Equipment'],true)||$capacity===false||$capacity<1||$capacity>10000||!scalar('SELECT COUNT(*) FROM campus_offices WHERE id=?',[$office]))throw new InvalidArgumentException('Choose a type, reviewing office, name, location, and capacity between 1 and 10000.');
 $values=[$name,$kind,$location,$capacity,$office,isset($_POST['approval_required'])?1:0,isset($_POST['active'])?1:0];
 if($id){$save=db()->prepare('UPDATE campus_resources SET name=?,kind=?,location=?,capacity=?,office_id=?,approval_required=?,active=?,revision=revision+1 WHERE id=? AND revision=?');$save->execute([...$values,$id,(int)($_POST['revision']??-1)]);if(!$save->rowCount())throw new InvalidArgumentException('This facility changed. Reload its settings.');}else db()->prepare('INSERT INTO campus_resources(name,kind,location,capacity,office_id,approval_required,active) VALUES(?,?,?,?,?,?,?)')->execute($values);
 log_activity(current_user()['id'],'Facility configured',$name);set_flash('success','Facility saved. Existing reservations keep their scheduled time.');redirect('facilities.php');
}catch(InvalidArgumentException $e){$error=$e->getMessage();}
$resources=rows('SELECT * FROM campus_resources ORDER BY name');$offices=option_list('campus_offices','name');render_header('Manage facilities'); ?>
<div class="page-title"><div><h1>Manage facilities</h1><p>Configure actual rooms, laboratories, or individually reservable equipment. Reservations are exclusive for the selected resource; capacity is information, not seat-based booking.</p></div><a class="btn btn-outline-primary" href="../shared/facilities.php">Reservation calendar</a></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?>
<?php foreach([...$resources,['id'=>0,'name'=>'','kind'=>'Room','location'=>'','capacity'=>1,'office_id'=>0,'approval_required'=>1,'active'=>1,'revision'=>0]] as $r): ?><section class="panel"><h2><?= $r['id']?e($r['name']):'Add a facility' ?></h2><form method="post" class="campus-form"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><input type="hidden" name="revision" value="<?= (int)$r['revision'] ?>"><label>Facility name<input name="name" value="<?= e($r['name']) ?>" class="form-control" minlength="3" maxlength="120" required></label><label for="facility-kind-<?= (int)$r['id'] ?>">Resource type</label><select id="facility-kind-<?= (int)$r['id'] ?>" name="kind" class="form-select"><?php foreach(['Room','Laboratory','Equipment'] as $kind): ?><option <?= $kind===$r['kind']?'selected':'' ?>><?= e($kind) ?></option><?php endforeach; ?></select><label>Location<input name="location" value="<?= e($r['location']) ?>" class="form-control" maxlength="160" required></label><label>Capacity / information<input name="capacity" type="number" min="1" max="10000" value="<?= (int)$r['capacity'] ?>" class="form-control" required></label><label for="facility-office-<?= (int)$r['id'] ?>">Reviewing office</label><select id="facility-office-<?= (int)$r['id'] ?>" name="office_id" class="form-select" required><option value="">Choose office</option><?php foreach($offices as $o): ?><option value="<?= (int)$o['id'] ?>" <?= (int)$o['id']===(int)$r['office_id']?'selected':'' ?>><?= e($o['label']) ?></option><?php endforeach; ?></select><label><input type="checkbox" name="approval_required" <?= $r['approval_required']?'checked':'' ?>> Require office approval</label><label><input type="checkbox" name="active" <?= $r['active']?'checked':'' ?>> Available for new reservations</label><button class="btn btn-primary">Save facility</button></form></section><?php endforeach;render_footer(); ?>
